<script setup lang="ts">
import BusinessStatus from '../components/BusinessStatus.vue';
import {businessRowClass} from '../business-status';
import {ref,reactive,computed,onMounted,nextTick} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage} from 'element-plus';
import {api,get,message} from '../api';
import {useAuth} from '../stores/auth';
import {label,transportMode,date,ton,money} from '../fulfillment';
import IntermodalGantt from '../components/IntermodalGantt.vue';
import IntermodalStageDetail from '../components/IntermodalStageDetail.vue';
const auth=useAuth(),route=useRoute(),router=useRouter(),loading=ref(false),busy=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),selected=ref<any[]>([]),table=ref<any>();
const canWrite=computed(()=>auth.can('service:write')&&auth.user?.businessEntity.type==='CARRIER');
const filters=reactive<any>({waybill:'',trader:'',carrier:'',origin:'',destination:'',cargo:'',status:'',period:[],page:1,pageSize:10});
const statuses:Record<string,string>={PENDING:'待执行',IN_PROGRESS:'执行中',COMPLETED:'已完成'},stageStatuses:Record<string,string>={DRAFT:'待提交',SUBMITTED:'执行中',COMPLETED:'已完成'},sources:Record<string,string>={CONTRACT:'合同费用',DRIVER:'司机回传',OTHER:'其他费用'};
const detail=ref<any>(),stageId=ref('');
const ganttBusiness=ref<any>();
const completeDialog=ref(false),completionRows=ref<any[]>([]),feeChoices=reactive<Record<string,string[]>>({}),formError=ref('');
const sum=(b:any)=>b.serviceFees.filter((f:any)=>feeChoices[b.id]?.includes(f.id)).reduce((n:number,f:any)=>n+f.amountCents,0);
const completionTotal=computed(()=>completionRows.value.reduce((n:number,b:any)=>n+sum(b),0));
async function load(){loading.value=true;error.value='';try{const q:any=Object.fromEntries(Object.entries(filters).filter(([k,v])=>k!=='period'&&v!==''));if(filters.period?.length){q.from=filters.period[0];q.to=filters.period[1];}const result=await get('/intermodal',q);rows.value=result.items;total.value=result.total;selected.value=[];await nextTick();const match=rows.value.find(b=>b.id===route.query.businessId||b.packageId===route.query.packageId);if(match)table.value?.toggleRowExpansion(match,true);}catch(e){error.value=message(e);}finally{loading.value=false;}}
function reset(){Object.assign(filters,{waybill:'',trader:'',carrier:'',origin:'',destination:'',cargo:'',status:'',period:[],page:1});router.replace({query:{}});load();}
function startTracking(b:any){window.open(router.resolve('/services/'+b.id+'/tracking').href,'_blank','noopener');}
async function inspect(b:any,s:any){try{detail.value=await get('/intermodal/'+b.id);stageId.value=s.id;}catch(e){error.value=message(e);}}
async function showGantt(b:any){try{ganttBusiness.value=await get('/intermodal/'+b.id);}catch(e){error.value=message(e);}}
async function beginComplete(){if(!selected.value.length)return;busy.value=true;formError.value='';try{const all=[];for(const b of selected.value){const fresh=await get('/intermodal/'+b.id);if(!fresh.readyToComplete){error.value='所选运单还有未完成阶段，请刷新后重新选择';return;}all.push(fresh);feeChoices[b.id]=fresh.serviceFees.filter((f:any)=>f.selected).map((f:any)=>f.id);}completionRows.value=all;completeDialog.value=true;}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function completeBusinesses(){busy.value=true;formError.value='';try{if(completionRows.value.some(b=>!feeChoices[b.id]?.length)){formError.value='每个运单至少勾选一项对账费用';return;}const result=(await api.post('/intermodal/complete',{items:completionRows.value.map(b=>({businessId:b.id,version:b.version,feeIds:feeChoices[b.id]}))})).data.data;completeDialog.value=false;detail.value=undefined;await load();ElMessage.success(`${result.items.length} 个运单已完成，账单已发送至账单管理（未对账）`);}catch(e){formError.value=message(e);}finally{busy.value=false;}}
const selectable=(b:any)=>b.readyToComplete;
onMounted(async()=>{if(route.query.businessId){try{const b=await get('/intermodal/'+route.query.businessId);filters.waybill=b.waybillNo;}catch{}}else if(route.query.packageId){try{const c=await get('/contracts/'+route.query.packageId);if(c.business)filters.waybill=c.business.waybillNo;}catch{}}await load();});
</script>
<template><div class="intermodal-page"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-form class="service-filters" label-position="left" @submit.prevent="filters.page=1;load()"><el-form-item label="运单 / 合同号"><el-input v-model="filters.waybill" placeholder="输入编号" clearable aria-label="运单或合同号"/></el-form-item><el-form-item label="粮食贸易商"><el-input v-model="filters.trader" placeholder="企业名称" clearable/></el-form-item><el-form-item label="物流运营企业"><el-input v-model="filters.carrier" placeholder="企业名称" clearable/></el-form-item><el-form-item label="计划发运时间"><el-date-picker v-model="filters.period" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item label="起运地"><el-input v-model="filters.origin" placeholder="起运地址" clearable/></el-form-item><el-form-item label="目的地"><el-input v-model="filters.destination" placeholder="目的地址" clearable/></el-form-item><el-form-item label="货物类型"><el-input v-model="filters.cargo" placeholder="粮食品种" clearable/></el-form-item><el-form-item label="进度"><el-select v-model="filters.status" clearable placeholder="全部进度" aria-label="运单进度"><el-option v-for="(name,key) in statuses" :key="key" :value="key" :label="name"/></el-select></el-form-item><div class="service-query-actions"><el-button @click="reset">重置</el-button><el-button type="primary" native-type="submit" :loading="loading">查询</el-button></div></el-form>
<section class="service-list"><header class="service-list-header"><div><strong>联运运单</strong><span>{{total}} 个运单</span><span v-if="selected.length" class="selection-count">已选择 {{selected.length}} 个</span></div><div><el-button v-if="canWrite" type="primary" :disabled="!selected.length" :loading="busy" @click="beginComplete">业务完成</el-button></div></header><el-table ref="table" :row-class-name="businessRowClass" :data="rows" row-key="id" v-loading="loading" @selection-change="(v:any)=>selected=v"><el-table-column v-if="canWrite" type="selection" width="44" :selectable="selectable"/><el-table-column type="expand" width="42"><template #default="{row:b}"><div class="waybill-expanded"><div class="expanded-heading"><h3>运输阶段 <small>{{b.stages.filter((s:any)=>s.status==='COMPLETED').length}} / {{b.stages.length}} 已完成</small></h3></div><el-table :data="b.stages" row-key="id" class="stage-table"><el-table-column type="expand" width="36"><template #default="{row:s}"><div class="stage-expanded"><el-table v-if="s.mode==='ROAD'&&s.tasks.length" :data="s.tasks" size="small"><el-table-column label="车辆 / 司机" min-width="170"><template #default="{row:t}"><b>{{t.vehicle?.plate||t.resource}}</b><small>{{t.driver?.displayName||'—'}} · {{t.driver?.phone||'—'}}</small></template></el-table-column><el-table-column label="车辆任务号" prop="businessNo" min-width="190"/><el-table-column label="实际回传数量" width="125"><template #default="{row:t}">{{t.feedbackSubmittedAt||t.unloadedKg>0?ton(t.unloadedKg||t.feedback?.quantityKg||0):'待过磅'}}</template></el-table-column><el-table-column label="开始 / 预计结束" min-width="200"><template #default="{row:t}">{{date(t.plannedStartAt)}}<small>{{date(t.plannedEndAt)}}</small></template></el-table-column><el-table-column label="司机反馈" min-width="120"><template #default="{row:t}">{{t.feedbackSubmittedAt?'业务信息已回传':label(t.status)}}<small v-if="t.feedbackSubmittedAt">签收 {{ton(t.unloadedKg)}}</small></template></el-table-column></el-table><div v-else class="transport-resource"><template v-if="s.mode==='WATER'"><span>船名 <b>{{s.vessel||'待填写'}}</b></span><span>航次 <b>{{s.voyage||'待填写'}}</b></span><span>提单号 <b>{{s.billOfLading||'待填写'}}</b></span><span>{{s.containerized?'箱号':'过磅单'}} <b>{{s.containerized?s.boxes.join('、')||'待填写':s.weightTicketNo||'待填写'}}</b></span></template><span v-else-if="s.mode==='RAIL'">铁路运单号 <b>{{s.railWaybillNo||'待填写'}}</b></span><span v-else>暂无车辆任务</span></div></div></template></el-table-column><el-table-column label="阶段" width="108"><template #default="{row:s}"><span class="mode-dot" :class="s.mode.toLowerCase()"/>{{transportMode(s.mode)}}</template></el-table-column><el-table-column label="运输路线" min-width="240"><template #default="{row:s}">{{s.origin}} → {{s.destination}}</template></el-table-column><el-table-column label="数量 / 装载" width="130"><template #default="{row:s}">{{ton(s.quantityKg)}}<small>{{s.containerized?'集装箱':'散货'}}</small></template></el-table-column><el-table-column label="开始 / 预计结束" min-width="190"><template #default="{row:s}">{{date(s.plannedStartAt)}}<small>{{date(s.plannedEndAt)}}</small></template></el-table-column><el-table-column label="阶段进度" width="106"><template #default="{row:s}"><BusinessStatus :status="s.status" :label="stageStatuses[s.status]" compact/></template></el-table-column><el-table-column label="操作" width="155" fixed="right"><template #default="{row:s}"><el-button link type="primary" @click="inspect(b,s)">详情</el-button></template></el-table-column></el-table><div class="waybill-fees"><strong>合同约定费用 {{money(b.package.totalCents)}}</strong><span>全程费用只计入一次 · {{b.package.snapshot.loadingType==='CONTAINER'?'集装箱':'散货'}}</span><router-link v-for="bill in b.bills" :key="bill.id" :to="'/billing/bills?id='+bill.id">查看账单 {{bill.businessNo}} →</router-link></div></div></template></el-table-column><el-table-column label="运单号 / 合同号" min-width="205"><template #default="{row}"><b class="waybill-number business-number">{{row.waybillNo}}</b><router-link :to="'/contracts/performance?id='+row.packageId" class="contract-number">{{row.package.businessNo}}</router-link></template></el-table-column><el-table-column label="贸易商 / 物流运营企业" min-width="170"><template #default="{row}">{{row.trader}}<small>{{row.carrier}}</small></template></el-table-column><el-table-column label="运输路线" min-width="200"><template #default="{row}"><span class="route-label">{{row.origin}}<span>→</span>{{row.destination}}</span></template></el-table-column><el-table-column label="货物" width="95"><template #default="{row}"><b>{{row.cargo}}</b><small>{{ton(row.package.quantityKg)}}</small></template></el-table-column><el-table-column label="进度" width="118"><template #default="{row}"><BusinessStatus :status="row.status" :label="statuses[row.status]" compact/><div v-if="row.readyToComplete" class="ready-hint"><BusinessStatus status="PENDING" label="待业务完成" compact/></div><small v-else-if="row.package.status==='DRAFT'">合同待生效</small></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button v-if="canWrite&&row.status!=='COMPLETED'&&row.package.status==='EFFECTIVE'" link type="primary" @click="startTracking(row)">开始跟踪</el-button><el-button v-else link type="primary" @click="table?.toggleRowExpansion(row)">查看过程</el-button><el-button link type="primary" @click="showGantt(row)">发运甘特图</el-button></template></el-table-column><template #empty><el-empty description="暂无联运运单，运输合同生效后自动生成" :image-size="70"/></template></el-table><footer class="service-pagination"><el-pagination v-model:current-page="filters.page" v-model:page-size="filters.pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @change="load"/></footer></section>
<el-dialog :model-value="!!ganttBusiness" title="运单发运甘特图" width="1100px" @close="ganttBusiness=undefined"><template v-if="ganttBusiness"><div class="gantt-modal-summary"><strong>{{ganttBusiness.waybillNo}}</strong><span>{{ganttBusiness.cargo}} · {{ton(ganttBusiness.package.quantityKg)}}</span><BusinessStatus :status="ganttBusiness.status" :label="statuses[ganttBusiness.status]"/></div><p class="gantt-modal-route">{{ganttBusiness.origin}} → {{ganttBusiness.destination}}</p><IntermodalGantt :stages="ganttBusiness.stages"/><p class="gantt-modal-note">时间条展示计划开始至预计结束；鼠标移入可查看计划时间及实际完成时间。</p></template></el-dialog>
<IntermodalStageDetail v-if="detail" :business="detail" :stage-id="stageId" :can-write="false" @close="detail=undefined" @changed="load"/>
<el-dialog v-model="completeDialog" title="业务完成与账单汇总" width="960px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><p class="completion-note">核对并勾选每个运单的费用。确认后运输进度更新为已完成，每个运单生成一张未对账账单。</p><article v-for="b in completionRows" :key="b.id" class="completion-waybill"><header><strong>{{b.waybillNo}}</strong><span>{{b.cargo}} · {{ton(b.package.quantityKg)}}</span><b>{{money(sum(b))}}</b></header><el-checkbox-group v-model="feeChoices[b.id]"><div v-for="f in b.serviceFees" :key="f.id" class="completion-fee"><el-checkbox :value="f.id"><span>{{f.name}} <em>{{sources[f.source]}}{{f.stageId?' · 第 '+b.stages.find((s:any)=>s.id===f.stageId)?.sequence+' 阶段':''}}</em></span></el-checkbox><span>{{f.description||'—'}}</span><strong>{{money(f.amountCents)}}</strong></div></el-checkbox-group></article><template #footer><span class="completion-sum">{{completionRows.length}} 个运单 · 合计 <strong>{{money(completionTotal)}}</strong></span><el-button @click="completeDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="completeBusinesses">完成业务并生成账单</el-button></template></el-dialog>
</div></template>
<style scoped>
.intermodal-page{display:flex;flex-direction:column;gap:16px}.service-filters{background:#fff;border:1px solid #e4e8ee;border-radius:9px;padding:20px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px 24px}.service-filters :deep(.el-form-item){margin:0;align-items:center}.service-filters :deep(.el-form-item__label){font-size:12px;white-space:nowrap}.service-filters :deep(.el-select),.service-filters :deep(.el-date-editor){width:100%;min-width:0}.service-query-actions{grid-column:1/-1;display:flex;justify-content:flex-end}.service-list{background:#fff;border:1px solid #e4e8ee;border-radius:9px;overflow:hidden}.service-list-header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px}.service-list-header>div{display:flex;align-items:center;gap:12px}.service-list-header strong{font-size:16px}.service-list-header span{font-size:12px;color:#8894a4}.service-list-header .selection-count{color:#e72b32}.service-list :deep(.el-table){font-size:13px}.service-list :deep(th.el-table__cell){background:#f7f8fa;color:#697586;font-size:12px}.service-list :deep(.el-table__cell){padding:15px 0}.service-list :deep(.cell small){display:block;font-size:11px;color:#8994a4;margin-top:4px}.waybill-number{font-size:13px;font-weight:600;color:#263140;display:block}.contract-number{display:block;font-size:11px;margin-top:5px;color:#8a94a2;text-decoration:none}.route-label{font-weight:500;line-height:1.7}.route-label>span{margin:0 8px;color:#a7afbb}.service-pagination{padding:20px;display:flex;justify-content:flex-end}.waybill-expanded{padding:20px 30px;background:#fafbfc;border-top:1px solid #ecf0f4}.expanded-heading{display:flex;align-items:center;justify-content:space-between;margin:0 0 15px}.expanded-heading h3{margin:0;font-size:14px}.expanded-heading small{margin-left:12px;font-weight:400;color:#8a94a2;font-size:12px}.stage-table{border:1px solid #e7ebf0;border-radius:6px}.stage-expanded{padding:12px 24px;background:#fff}.mode-dot{width:7px;height:7px;display:inline-block;border-radius:50%;margin-right:8px}.mode-dot.road{background:#e6504f}.mode-dot.rail{background:#8b6ac2}.mode-dot.water{background:#3490bf}.gantt-section{margin-top:22px;background:#fff;border:1px solid #e7ebf0;padding:16px 20px;border-radius:7px}.gantt-section h4{margin:0 0 14px;font-size:13px}.waybill-fees{display:flex;flex-wrap:wrap;align-items:center;gap:15px;font-size:12px;padding:16px 0 0}.waybill-fees span{color:#929baa}.waybill-fees a{color:#e72b32;text-decoration:none}.transport-resource{display:flex;flex-wrap:wrap;gap:12px 28px;font-size:12px;color:#8a94a2}.transport-resource b{color:#384454;margin-left:8px;font-weight:500}.completion-note{font-size:13px;color:#7b8796;margin:0 0 20px}.completion-waybill{border:1px solid #e5eaf0;border-radius:7px;margin:15px 0;overflow:hidden}.completion-waybill header{display:flex;align-items:center;gap:16px;background:#f7f8fa;padding:15px;font-size:13px}.completion-waybill header>span{color:#8a94a2}.completion-waybill header>b{margin-left:auto;color:#e72b32}.completion-fee{display:grid;grid-template-columns:270px 1fr 130px;align-items:center;gap:12px;padding:12px 16px;border-top:1px solid #edf0f4;font-size:12px}.completion-fee em{font-style:normal;display:block;font-size:11px;color:#8a94a2}.completion-fee>span{color:#8a94a2}.completion-fee>strong{text-align:right}.completion-sum{margin-right:20px;font-size:13px}.completion-sum strong{color:#e72b32}.service-list :deep(.ready-hint){color:#e72b32!important}@media(max-width:1250px){.service-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}
.gantt-modal-summary{display:flex;align-items:center;gap:16px;margin-bottom:12px}.gantt-modal-summary strong{font-size:16px}.gantt-modal-summary span,.gantt-modal-route,.gantt-modal-note{font-size:12px;color:#8894a4}.gantt-modal-route{margin-bottom:24px}.gantt-modal-note{margin-top:22px}</style>
